/**
 * Family Members — pure view-model helpers
 *
 * A Family Member is a row returned by the `get_family_members()` RPC: one
 * person who shares a family's expenses, identified by their primary email.
 * These helpers are dependency-free (no Supabase) so they can be unit-tested in
 * the node environment.
 */

export type FamilyMember = {
	user_id: string;
	email: string;
	role: string;
	status: string;
	is_default: boolean;
};

/** A Family Member annotated for display. */
export type DecoratedFamilyMember = FamilyMember & {
	/** True when this member is the person currently signed in. */
	isCurrentUser: boolean;
	/** True when this member created the family (`role = 'owner'`). */
	isOwner: boolean;
};

/**
 * Annotate each member with the flags the Profile page renders as badges.
 *
 * @param members       the roster from `get_family_members()`
 * @param currentUserId the signed-in user's id (from the session)
 */
export function decorateFamilyMembers(
	members: FamilyMember[],
	currentUserId: string
): DecoratedFamilyMember[] {
	return members.map((member) => ({
		...member,
		isCurrentUser: member.user_id === currentUserId,
		isOwner: member.role === 'owner'
	}));
}

