import { describe, it, expect } from 'vitest';
import { decorateFamilyMembers, type FamilyMember } from './familyMembers';

const member = (over: Partial<FamilyMember>): FamilyMember => ({
	user_id: 'u-default',
	email: 'someone@example.com',
	role: 'member',
	status: 'active',
	is_default: true,
	...over
});

describe('decorateFamilyMembers', () => {
	it('flags the row whose user_id matches the current user', () => {
		const members = [
			member({ user_id: 'u-1', email: 'a@example.com' }),
			member({ user_id: 'u-2', email: 'b@example.com' })
		];

		const decorated = decorateFamilyMembers(members, 'u-2');

		expect(decorated.map((m) => m.isCurrentUser)).toEqual([false, true]);
	});

	it('marks no one as the current user when the id matches nobody', () => {
		const members = [member({ user_id: 'u-1' }), member({ user_id: 'u-2' })];

		const decorated = decorateFamilyMembers(members, 'someone-else');

		expect(decorated.every((m) => !m.isCurrentUser)).toBe(true);
	});

	it('flags owners by role and leaves plain members unmarked', () => {
		const members = [
			member({ user_id: 'u-1', role: 'owner' }),
			member({ user_id: 'u-2', role: 'member' })
		];

		const decorated = decorateFamilyMembers(members, 'nobody');

		expect(decorated.map((m) => m.isOwner)).toEqual([true, false]);
	});

	it('can flag the same row as both the current user and the owner', () => {
		const decorated = decorateFamilyMembers([member({ user_id: 'me', role: 'owner' })], 'me');

		expect(decorated[0].isCurrentUser).toBe(true);
		expect(decorated[0].isOwner).toBe(true);
	});

	it('preserves the underlying fields and order', () => {
		const members = [
			member({ user_id: 'u-1', email: 'a@example.com' }),
			member({ user_id: 'u-2', email: 'b@example.com' })
		];

		const decorated = decorateFamilyMembers(members, 'u-1');

		expect(decorated.map((m) => m.email)).toEqual(['a@example.com', 'b@example.com']);
		expect(decorated[0]).toMatchObject({ user_id: 'u-1', role: 'member', status: 'active' });
	});

	it('returns an empty array for an empty roster', () => {
		expect(decorateFamilyMembers([], 'u-1')).toEqual([]);
	});
});

